import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.DvE3tBec.js";const u=JSON.parse('{"title":"Getting started for back-end providers","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/0.4/developers/backends/getting-started.md","filePath":"documentation/0.4/developers/backends/getting-started.md","lastUpdated":1575560999000}'),n={name:"documentation/0.4/developers/backends/getting-started.md"};function i(s,e,d,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started-for-back-end-providers" tabindex="-1">Getting started for back-end providers <a class="header-anchor" href="#getting-started-for-back-end-providers" aria-label="Permalink to &quot;Getting started for back-end providers&quot;">​</a></h1><p>As a back-end provider who wants to provide its datasets, processes and infrastructure to a broader audience through a standardized interface you may want to implement a driver for openEO.</p><p>First of all, you should go through the list of <a href="https://github.com/Open-EO" target="_blank" rel="noreferrer">openEO repositories</a> and check whether there is already a back-end driver that suits your needs. In this case you don&#39;t need to develop your own driver, but &quot;only&quot; need to ingest your data, adopt your required processes and set up the infrastructure. Please follow the documentation for the individual driver you want to use.</p><p>If your preferred technology has no back-end driver yet, you may consider writing your own driver. All software written for openEO should follow the <a href="/documentation/software-guidelines.html">software development guidelines</a>.</p><p>You certainly need to understand the <a href="./../../glossary.html">glossary</a>, the <a href="./../arch.html">architecture</a> of openEO and the concepts behind <a href="./../api/">processes</a> and <a href="./../api/">process graphs</a>. This helps you read and understand the <a href="./../api/reference.html">API specification</a>. Technical API related documents like <a href="./../api/">CORS</a> and <a href="./../api/errors.html">error handing</a> should be read, too.</p><p>If you do not want to start from scratch, you could try to generate a server stub from the <a href="https://www.openapis.org/" target="_blank" rel="noreferrer">OpenAPI 3.0</a>-based <a href="./../api/reference.html">API specification</a> with the <a href="https://github.com/OpenAPITools/openapi-generator" target="_blank" rel="noreferrer">OpenAPI Generator</a>. If you are using Python to implement your driver you may reuse some common modules of the existing driver implementations:</p><ul><li><a href="https://github.com/Open-EO/openeo-python-driver" target="_blank" rel="noreferrer">Python Driver Commons</a></li></ul><p>You can implement a back-end in iterations. It is recommended to start by implementing the <a href="./../api/reference.html#tag/Capabilities">Capabilities</a> microservice. <a href="./../api/reference.html#tag/EO-Data-Discovery">EO Data Discovery</a>, <a href="./../api/reference.html#tag/Process-Discovery">Process Discovery</a> are important for the client libraries to be available, too. Afterwards you should implement <a href="./../api/reference.html#tag/Batch-Job-Management">Batch Job Management</a> or <a href="./../api/reference.html#/paths/~1result/post">synchronous data processing</a>. All other microservices can be added later and are not strictly required to run openEO services. Keep in mind that you don&#39;t need to implement all endpoints in the first iteration and that you can specify in the Capabilities, which endpoints you are supporting.</p><p>For example, you could start by implementing the following endpoints in the first iteration:</p><ul><li>Well-Known Document: <code>GET /.well-known/openeo</code></li><li>Capabilities: <code>GET /</code> and <code>GET /output_formats</code></li><li>Data discovery: <code>GET /collections</code> and <code>GET /collections/{collection_id}</code></li><li>Process discovery: <code>GET /processes</code></li><li>Data processing: <code>POST /result</code></li><li>Authentication (if required): <code>GET /credentials/basic</code></li></ul><p>Afterwards you can already start experimenting with your first process graphs and process EO data with our client libraries on your back-end.</p>',11)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
